def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1

    # Test at round 5 if opponent has never defected
    if n == 5 and opp_def == 0:
        return 'D'

    # Apology after test if opponent cooperated at round 5
    if (n == 6 or n == 7) and len(history) > 5 and history[5] == ('D', 'C'):
        return 'C'

    # Exploit mode: opponent never defected and we are past round 8
    if n >= 8 and opp_def == 0:
        return 'D'

    # Normal TFT with forgiveness
    last_me, last_opp = history[-1]
    if last_opp == 'C':
        return 'C'
    else:
        if last_me == 'C':
            return 'D'
        else:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
